<?php
require __DIR__.'/../../includes/bootstrap.php';require_role(['admin']);$de=$_GET['de']??date('Y-m-d');$ate=$_GET['ate']??date('Y-m-d');$q=db()->prepare('SELECT r.*,a.nome aluno,t.nome turma,u.nome usuario FROM scp_registros_acesso r JOIN scp_alunos a ON a.id=r.aluno_id LEFT JOIN scp_turmas t ON t.id=a.turma_id JOIN scp_usuarios u ON u.id=r.usuario_id WHERE DATE(r.registrado_em) BETWEEN ? AND ? ORDER BY r.registrado_em DESC');$q->execute([$de,$ate]);$rows=$q->fetchAll();layout_header('Relatórios');?>
<h1>Movimentações</h1><form class="row g-2 mb-3"><div class="col"><input type="date" class="form-control" name="de" value="<?=e($de)?>"></div><div class="col"><input type="date" class="form-control" name="ate" value="<?=e($ate)?>"></div><div class="col-auto"><button class="btn btn-primary">Filtrar</button></div></form><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data</th><th>Aluno</th><th>Turma</th><th>Tipo</th><th>Portaria</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d/m/Y H:i',strtotime($r['registrado_em'])))?></td><td><?=e($r['aluno'])?></td><td><?=e($r['turma']??'-')?></td><td><?=e($r['tipo'])?></td><td><?=e($r['usuario'])?></td></tr><?php endforeach?></tbody></table></div></div><?php layout_footer();

